 'e^-kt':(lambda q: np.exp(-q[0]*tv),1),
 't^a e^-kt':(lambda q: tv**q[1]*np.exp(-q[0]*tv),2),
 '1/(1+kt)':(lambda q: 1/(1+q[0]*tv),1),
 't^a':(lambda q: tv**q[0],1),
 'e^-k/t':(lambda q: np.exp(-q[0]/tv),1),
 'e^-k t^2':(lambda q: np.exp(-q[0]*tv**2),1),
}
Gs={'A^p':(lambda q,Av: np.abs(Av)**q,1), 'exp(-kA)':(lambda q,Av: np.exp(-q*Av),1), 'A^p e^-A':(lambda q,Av: Av**q*np.exp(-Av),1), 'none':(lambda q,Av: np.ones_like(Av),0)}
res=[]
for fn,(ff,fp) in Fs.items():
  for gn,(gf,gp) in Gs.items():
    best=None
    for s in range(8):
        rng=np.random.RandomState(s)
        def model(q):
            f=ff(q[:fp]); 
            pA=q[fp] if gp else 0
            g=gf(q[fp], Av) if False else None
            if gn=='A^p': h=np.abs(Av)**q[fp+1]
