            elif gn=='A^p e^-A': h=Av**q[fp+1]*np.exp(-Av)
            else: h=np.ones_like(Av)
            X=np.column_stack([L2, h, f*np.abs(Av)**q[fp+2 if False else fp+1] ]) if False else None
